"""`.Gag UV`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.Gag UV'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Vector', 'NodeSocketVector')
    t.socket('INPUT', 'Frame', 'NodeSocketFloat')
    t.socket('INPUT', 'Angle speed', 'NodeSocketFloat')
    t.socket('INPUT', 'Size speed', 'NodeSocketFloat')
    t.socket('INPUT', 'Size width', 'NodeSocketFloat')
    t.socket('INPUT', 'Tile X', 'NodeSocketFloat', default_value=1.0)
    t.socket('INPUT', 'Tile Y', 'NodeSocketFloat', default_value=1.0)

    t.node('NodeGroupInput', 'Group Input', props={
        'location': (-1200.0, 0.0),
    })
    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (900.0, 0.0),
    })
    t.node('ShaderNodeUVMap', 'UV Map', props={
        'location': (-1000.0, 300.0),
    })
    t.node('ShaderNodeVectorMath', 'Vector Math', inputs={'Vector_001': (0.5, 0.5, 0.0)}, props={
        'location': (-800.0, 300.0),
        'operation': 'SUBTRACT',
    })
    t.node('ShaderNodeMath', 'Math', props={
        'location': (-1000.0, 100.0),
        'operation': 'MULTIPLY',
    })
    t.node('ShaderNodeMath', 'Math.001', inputs={'Value_001': 0.2}, props={
        'location': (-800.0, 100.0),
        'operation': 'MULTIPLY',
    })
    t.node('ShaderNodeMath', 'Math.002', inputs={'Value_001': 3.0}, props={
        'location': (-1000.0, -100.0),
        'operation': 'DIVIDE',
    })
    t.node('ShaderNodeMath', 'Math.003', props={
        'location': (-850.0, -100.0),
        'operation': 'MULTIPLY',
    })
    t.node('ShaderNodeMath', 'Math.004', props={
        'location': (-700.0, -100.0),
        'operation': 'SINE',
    })
    t.node('ShaderNodeMath', 'Math.005', props={
        'location': (-550.0, -100.0),
        'operation': 'MULTIPLY',
    })
    t.node('ShaderNodeMath', 'Math.006', inputs={'Value_001': 0.0, 'Value_002': 1e-06}, props={
        'location': (-700.0, -250.0),
        'operation': 'COMPARE',
    })
    t.node('ShaderNodeMath', 'Math.007', inputs={'Value': 2.0}, props={
        'location': (-550.0, -250.0),
        'operation': 'SUBTRACT',
    })
    t.node('ShaderNodeMath', 'Math.008', props={
        'location': (-400.0, -150.0),
    })
    t.node('ShaderNodeCombineXYZ', 'Combine XYZ', props={
        'location': (-600.0, 100.0),
    })
    t.node('ShaderNodeCombineXYZ', 'Combine XYZ.001', inputs={'Z': 1.0}, props={
        'location': (-250.0, -150.0),
    })
    t.node('ShaderNodeMapping', 'Mapping', props={
        'location': (-100.0, 250.0),
        'vector_type': 'VECTOR',
    })
    t.node('ShaderNodeVectorMath', 'Vector Math.001', inputs={'Vector_001': (0.5, 0.5, 0.0)}, props={
        'location': (100.0, 250.0),
    })
    t.node('ShaderNodeMath', 'Math.009', inputs={'Value': 1.0}, props={
        'location': (-100.0, -400.0),
        'operation': 'DIVIDE',
    })
    t.node('ShaderNodeMath', 'Math.010', inputs={'Value': 1.0}, props={
        'location': (-100.0, -550.0),
        'operation': 'DIVIDE',
    })
    t.node('ShaderNodeCombineXYZ', 'Combine XYZ.002', inputs={'Z': 1.0}, props={
        'location': (100.0, -450.0),
    })
    t.node('ShaderNodeMapping', 'Mapping.001', props={
        'location': (300.0, 250.0),
        'vector_type': 'VECTOR',
    })
    t.node('ShaderNodeCombineXYZ', 'Combine XYZ.003', props={
        'location': (300.0, -300.0),
    })
    t.node('ShaderNodeMath', 'Math.011', props={
        'location': (100.0, -650.0),
        'operation': 'MODULO',
    })
    t.node('ShaderNodeMath', 'Math.012', props={
        'location': (200.0, -650.0),
        'operation': 'MULTIPLY',
    })
    t.node('ShaderNodeMath', 'Math.013', props={
        'location': (100.0, -800.0),
        'operation': 'MODULO',
    })
    t.node('ShaderNodeMath', 'Math.014', props={
        'location': (200.0, -800.0),
        'operation': 'MULTIPLY',
    })
    t.node('ShaderNodeVectorMath', 'Vector Math.002', props={
        'location': (550.0, 100.0),
    })

    t.link('UV Map', 'UV', 'Vector Math', 'Vector')
    t.link('Group Input', 'Frame', 'Math', 'Value')
    t.link('Group Input', 'Angle speed', 'Math', 'Value_001')
    t.link('Math', 'Value', 'Math.001', 'Value')
    t.link('Group Input', 'Size speed', 'Math.002', 'Value')
    t.link('Group Input', 'Frame', 'Math.003', 'Value')
    t.link('Math.002', 'Value', 'Math.003', 'Value_001')
    t.link('Math.003', 'Value', 'Math.004', 'Value')
    t.link('Math.004', 'Value', 'Math.005', 'Value')
    t.link('Group Input', 'Size width', 'Math.005', 'Value_001')
    t.link('Group Input', 'Size speed', 'Math.006', 'Value')
    t.link('Math.006', 'Value', 'Math.007', 'Value_001')
    t.link('Math.005', 'Value', 'Math.008', 'Value')
    t.link('Math.007', 'Value', 'Math.008', 'Value_001')
    t.link('Math.001', 'Value', 'Combine XYZ', 'Z')
    t.link('Math.008', 'Value', 'Combine XYZ.001', 'X')
    t.link('Math.008', 'Value', 'Combine XYZ.001', 'Y')
    t.link('Vector Math', 'Vector', 'Mapping', 'Vector')
    t.link('Combine XYZ', 'Vector', 'Mapping', 'Rotation')
    t.link('Combine XYZ.001', 'Vector', 'Mapping', 'Scale')
    t.link('Mapping', 'Vector', 'Vector Math.001', 'Vector')
    t.link('Group Input', 'Tile X', 'Math.009', 'Value_001')
    t.link('Group Input', 'Tile Y', 'Math.010', 'Value_001')
    t.link('Math.009', 'Value', 'Combine XYZ.002', 'X')
    t.link('Math.010', 'Value', 'Combine XYZ.002', 'Y')
    t.link('Vector Math.001', 'Vector', 'Mapping.001', 'Vector')
    t.link('Combine XYZ.002', 'Vector', 'Mapping.001', 'Scale')
    t.link('Group Input', 'Frame', 'Math.011', 'Value')
    t.link('Group Input', 'Tile X', 'Math.011', 'Value_001')
    t.link('Math.009', 'Value', 'Math.012', 'Value')
    t.link('Math.011', 'Value', 'Math.012', 'Value_001')
    t.link('Math.012', 'Value', 'Combine XYZ.003', 'X')
    t.link('Group Input', 'Frame', 'Math.013', 'Value')
    t.link('Group Input', 'Tile Y', 'Math.013', 'Value_001')
    t.link('Math.010', 'Value', 'Math.014', 'Value')
    t.link('Math.013', 'Value', 'Math.014', 'Value_001')
    t.link('Math.014', 'Value', 'Combine XYZ.003', 'Y')
    t.link('Mapping.001', 'Vector', 'Vector Math.002', 'Vector')
    t.link('Combine XYZ.003', 'Vector', 'Vector Math.002', 'Vector_001')
    t.link('Vector Math.002', 'Vector', 'Group Output', 'Vector')
    return t
